cd /workspace && python3 -c "
import plistlib, struct, io
# check plistlib error types on bad data
for data in (b'', b'\x00\x00\x00\x04zzzz', b'not a plist', b'\x0b\x00\x00\x00\x00'*3, b'<plist><dict></plist>'):
    try:
        v = plistlib.loads(data)
        print(repr(data[:12]), '->', v)
    except Exception as e:
        print(repr(data[:12]), '->', type(e).__module__+'.'+type(e).__name__, e)
# recursion
deep = b'<plist><array>' + b'<array>'*2000 + b'</array>'*2000 + b'</array></plist>'
try:
    v = plistlib.loads(deep); print('deep ok', len(v))
except Exception as e: print('deep ->', type(e).__name__, e)
import sys; print(sys.getrecursionlimit())
"
